import{_ as e}from"./chunks/img.Dck1PxLc.js";import{_ as r,C as t,c as n,o as a,j as i,G as l,a0 as s,a as o}from"./chunks/framework.DKRgXLPU.js";const d=JSON.parse('{"title":"Om Pétanque-akademiet","description":"","frontmatter":{},"headers":[],"relativePath":"no/about.md","filePath":"no/about.md"}');const g=r({name:"no/about.md"},[["render",function(r,d,g,k,p,m){const u=t("AdBanner"),h=t("AdInArticle");return a(),n("div",null,[d[0]||(d[0]=i("h1",{id:"om-petanque-akademiet",tabindex:"-1"},[o("Om Pétanque-akademiet "),i("a",{class:"header-anchor",href:"#om-petanque-akademiet","aria-label":'Permalink to "Om Pétanque-akademiet"'},"​")],-1)),l(u),d[1]||(d[1]=s('<h2 id="en-lidenskap-for-petanque" tabindex="-1">En lidenskap for petanque <a class="header-anchor" href="#en-lidenskap-for-petanque" aria-label="Permalink to &quot;En lidenskap for petanque&quot;">​</a></h2><p>Velkommen til Pétanque Academy, hvor en dyptliggende lidenskap for petanque har vært en drivkraft i over 45 år. Min reise med denne sporten har vært preget av dedikasjon, dyktighet og kontinuerlig entusiasme.</p><p>Pétanque er ikke bare et spill; det er en måte å knytte bånd, legge strategier og nyte naturen på, og jeg har vært så heldig å få oppleve dets mange fasetter i nesten et halvt århundre. Enten det er den presise plasseringen av en boule eller kameratskapet i terrenget, er min forpliktelse til pétanque fortsatt like sterk som alltid.</p><p><img src="'+e+'" alt="Patrik Wiik with friends"></p><p><em>Det er virkelig det som gjør petanque så spesielt å dele denne lidenskapen med venner. De utallige timene man bruker på terrenget, fylt med latter, vennskapelig konkurranse og delte historier, bygger bånd som varer livet ut.</em></p><hr><h2 id="mitt-oppdrag" tabindex="-1">Mitt oppdrag <a class="header-anchor" href="#mitt-oppdrag" aria-label="Permalink to &quot;Mitt oppdrag&quot;">​</a></h2><p>Pétanque Academys oppgave er å hjelpe elitespillere med å frigjøre sitt fulle potensial ved å ta tak i det mentale spillet – det ofte oversette aspektet som skiller gode spillere fra store spillere.</p><p>Gjennom denne nettsiden deler jeg:</p><ul><li><strong>Mentale spillrammeverk</strong> utviklet fra flere tiår med erfaring</li><li><strong>Praktiske verktøy og maler</strong> for målsetting og opplæring</li><li><strong>Workshop-metodologier</strong> for å bygge psykologisk trygghet</li><li><strong>Evidensbaserte tilnærminger</strong> til ytelse under press</li></ul><p>Dette handler ikke om teknisk coaching – det handler om å skape det mentale grunnlaget som lar dine tekniske ferdigheter skinne når det gjelder som mest.</p><hr><h2 id="hvorfor-jeg-opprettet-denne-nettsiden" tabindex="-1">Hvorfor jeg opprettet denne nettsiden <a class="header-anchor" href="#hvorfor-jeg-opprettet-denne-nettsiden" aria-label="Permalink to &quot;Hvorfor jeg opprettet denne nettsiden&quot;">​</a></h2><p>Etter over 45 år i petanque har jeg sett utallige talentfulle spillere slite ikke med teknikk, men med:</p><ul><li><strong>Indre kritiker</strong> som ødelegger selvtilliten etter feil</li><li><strong>Press</strong> som gjør at de spiller annerledes i konkurranser</li><li><strong>Mangel på struktur</strong> i mental trening</li><li><strong>Isolasjon</strong> i utviklingsreisen sin</li></ul><p>Dette nettstedet eksisterer for å endre på det. Alt innhold her er utformet for å være umiddelbart praktisk – maler du kan kopiere, rammeverk du kan bruke i dag og verktøy som fungerer i reell konkurranse.</p><hr>',17)),l(h),d[2]||(d[2]=s('<h2 id="ta-kontakt" tabindex="-1">Ta kontakt <a class="header-anchor" href="#ta-kontakt" aria-label="Permalink to &quot;Ta kontakt&quot;">​</a></h2><p>Jeg vil gjerne høre fra deg! Enten du har spørsmål, ønsker å dele erfaringene dine, eller er interessert i workshops og opplæring, er det bare å ta kontakt.</p><h3 id="kontaktinformasjon" tabindex="-1">Kontaktinformasjon <a class="header-anchor" href="#kontaktinformasjon" aria-label="Permalink to &quot;Kontaktinformasjon&quot;">​</a></h3><p><strong>E-post:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Facebook:</strong> <a href="https://www.facebook.com/patrik.wiik" target="_blank" rel="noreferrer">facebook.com/patrik.wiik</a></p><hr><h2 id="hjelp-meg-a-forbedre-dette-nettstedet" tabindex="-1">Hjelp meg å forbedre dette nettstedet <a class="header-anchor" href="#hjelp-meg-a-forbedre-dette-nettstedet" aria-label="Permalink to &quot;Hjelp meg å forbedre dette nettstedet&quot;">​</a></h2><p>Din tilbakemelding er uvurderlig! Denne nettsiden er i stadig utvikling basert på hva elitespillere faktisk trenger.</p><h3 id="jeg-vil-gjerne-høre-fra-deg-om" tabindex="-1">Jeg vil gjerne høre fra deg om: <a class="header-anchor" href="#jeg-vil-gjerne-høre-fra-deg-om" aria-label="Permalink to &quot;Jeg vil gjerne høre fra deg om:&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Hva ville hjelpe deg mest?</p><ul><li><p><strong>Hvilket innhold ønsker du å se mer av?</strong></p><ul><li>Flere mentale spillteknikker?</li><li>Flere praktiske maler?</li><li>Casestudier fra elitespillere?</li></ul></li><li><p><strong>Hva mangler på nettstedet?</strong></p><ul><li>Temaer som ikke er dekket? – Verktøy du skulle ønske fantes? – Ressurser du ikke finner?</li></ul></li><li><p><strong>Hva fungerer bra?</strong> – Hvilke sider har vært mest nyttige? – Hvilke verktøy har du egentlig brukt? – Hva gjorde den største forskjellen for deg?</p></li><li><p><strong>Hvordan kan jeg gjøre det bedre?</strong></p><ul><li>Forbedringer i navigasjonen?</li><li>Organisering av innhold? – Flere eksempler?</li><li>Ulike formater?</li></ul></li></ul></div><h3 id="send-meg-din-tilbakemelding" tabindex="-1">Send meg din tilbakemelding <a class="header-anchor" href="#send-meg-din-tilbakemelding" aria-label="Permalink to &quot;Send meg din tilbakemelding&quot;">​</a></h3><p><strong>Send dine tanker til:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Forslag til emnelinjer:</strong> – «Tilbakemelding fra nettstedet: [Emnet ditt]» – «Innholdsforespørsel: [Hva du trenger]» – «Suksesshistorie: [Hvordan den hjalp]» – «Forslag: [Din idé]»</p><p><strong>Hva som skal inkluderes:</strong></p><ul><li>Ditt nåværende nivå/erfaring</li><li>Hva du jobber med</li><li>Spesifikke tilbakemeldinger eller forespørsler</li><li>Eventuelle suksesshistorier med bruk av innholdet</li></ul><hr><h2 id="hva-andre-sier" tabindex="-1">Hva andre sier <a class="header-anchor" href="#hva-andre-sier" aria-label="Permalink to &quot;Hva andre sier&quot;">​</a></h2><details class="details custom-block"><summary>Tilbakemeldinger fra elitespillere</summary><p><em>«Det mentale spillinnholdet har fullstendig endret hvordan jeg nærmer meg konkurranse. Bare Inner Coach-rammeverket var verdt å finne dette nettstedet.»</em> — Regionsmester, Frankrike</p><p><em>«Endelig er det ingen som forstår teknikken som er problemet. Workshop-metodikken ga klubben vår en helt ny måte å trene på.»</em> — Landslagsspiller, Sverige</p><p><em>«Målmalen og dagbokmalen var akkurat det jeg trengte. Enkle, praktiske og faktisk brukbare.»</em> — Turneringsspiller, Spania</p></details><hr><h2 id="om-innholdet" tabindex="-1">Om innholdet <a class="header-anchor" href="#om-innholdet" aria-label="Permalink to &quot;Om innholdet&quot;">​</a></h2><p>Alt innhold på dette nettstedet er:</p><ul><li><strong>Gratis og tilgjengelig</strong> - Ingen betalingsmurer, intet skjult innhold</li><li><strong>Praktisk og handlingsrettet</strong> - Maler du kan bruke i dag</li><li><strong>Evidensbasert</strong> - Bygget på psykologisk forskning og over 45 års erfaring</li><li><strong>Oppdateres kontinuerlig</strong> - Nytt innhold lagt til basert på tilbakemeldingene dine</li></ul><hr><h2 id="personvern-og-informasjonskapsler" tabindex="-1">Personvern og informasjonskapsler <a class="header-anchor" href="#personvern-og-informasjonskapsler" aria-label="Permalink to &quot;Personvern og informasjonskapsler&quot;">​</a></h2><p>Dette nettstedet bruker Google AdSense for å støtte driften. Ved å bruke dette nettstedet godtar du Googles bruk av informasjonskapsler for personlig tilpasning av annonser og analyse.</p><p><strong>Vi respekterer personvernet ditt:</strong></p><ul><li>Ingen personopplysninger samles inn utover standard analysemetoder</li><li>Ingen e-postlister eller spam – Kontaktinformasjonen brukes kun til å svare på meldingene dine</li></ul><hr><h2 id="koble-til-og-del" tabindex="-1">Koble til og del <a class="header-anchor" href="#koble-til-og-del" aria-label="Permalink to &quot;Koble til og del&quot;">​</a></h2><p>Hvis du synes dette innholdet er verdifullt:</p><ul><li><strong>Del det</strong> med treningspartnerne dine</li><li><strong>Anbefal det</strong> til klubben din</li><li><strong>Lenke til den</strong> fra dine egne ressurser</li><li><strong>Gi tilbakemelding</strong> for å forbedre det</li></ul><p>Sammen kan vi heve det mentale petanque-spillet over hele verden.</p><hr>',33)),l(u),d[3]||(d[3]=i("p",null,[i("strong",null,"Takk for at du er en del av Pétanque Academy!")],-1)),d[4]||(d[4]=i("p",null,[i("em",null,"— Patrik Wiik")],-1))])}]]);export{d as __pageData,g as default};
